EmberViewport.prototype.loadParticleMesh=async function(mesh){
 if(this.meshLibrary.has(mesh.id))return;const T=Ember3D,bytes=Uint8Array.from(atob(mesh.data),character=>character.charCodeAt(0));
 const gltf=await new Promise((resolve,reject)=>new T.GLTFLoader().parse(bytes.buffer,'',resolve,reject));gltf.scene.updateMatrixWorld(true);const parts=[];
 gltf.scene.traverse(object=>{if(!object.isMesh)return;let geometry=object.geometry.clone();if(geometry.index)geometry=geometry.toNonIndexed();for(const key of Object.keys(geometry.attributes))if(!['position','normal','uv'].includes(key))geometry.deleteAttribute(key);if(!geometry.attributes.normal)geometry.computeVertexNormals();if(!geometry.attributes.uv)geometry.setAttribute('uv',new T.BufferAttribute(new Float32Array(geometry.attributes.position.count*2),2));geometry.applyMatrix4(object.matrixWorld);parts.push(geometry);});
 if(!parts.length)throw Error('The file contains no mesh geometry.');const geometry=T.mergeGeometries(parts);parts.forEach(part=>part.dispose());if(!geometry||geometry.attributes.position.count>600000)throw Error('Use a mesh with fewer than 200,000 triangles.');geometry.rotateX(Math.PI/2);geometry.computeBoundingBox();const size=geometry.boundingBox.getSize(new T.Vector3()),center=geometry.boundingBox.getCenter(new T.Vector3()),extent=Math.max(size.x,size.y,size.z);if(!Number.isFinite(extent)||extent<=0)throw Error('Mesh has no usable dimensions.');geometry.translate(-center.x,-center.y,-center.z);geometry.scale(2/extent,2/extent,2/extent);this.meshLibrary.set(mesh.id,geometry);
};
EmberViewport.prototype.renderMeshParticles=function(particles){
 const T=Ember3D;for(const bucket of this.meshBuckets.values())bucket.count=0;
 const matrix=new T.Matrix4(),position=new T.Vector3(),scale=new T.Vector3(),quaternion=new T.Quaternion(),axis=new T.Vector3(0,0,1),color=new T.Color();
 for(const particle of particles){const settings=particle.settings;if(settings?.renderer!=='mesh'||!this.meshLibrary.has(settings.meshRef))continue;const key=settings.meshRef+':'+settings.glow+':'+!!settings.anime+':'+(settings.animeSteps??3)+':'+(settings.animeOutline??8);let bucket=this.meshBuckets.get(key);
  if(!bucket){const geometry=this.meshLibrary.get(settings.meshRef).clone();geometry.setAttribute('instanceOpacity',new T.InstancedBufferAttribute(new Float32Array(this.max),1));const material=new T.MeshBasicMaterial({color:0xffffff,transparent:true,depthWrite:false,blending:settings.glow&&!settings.anime?T.AdditiveBlending:T.NormalBlending});material.customProgramCacheKey=()=>key;material.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 vAnimeNormal;varying vec3 vAnimeView;attribute float instanceOpacity;varying float vInstanceOpacity;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvInstanceOpacity=instanceOpacity;vAnimeNormal=normalize(mat3(modelViewMatrix)*mat3(instanceMatrix)*normal);vAnimeView=normalize(-(modelViewMatrix*instanceMatrix*vec4(position,1.0)).xyz);');shader.fragmentShader='varying vec3 vAnimeNormal;varying vec3 vAnimeView;varying float vInstanceOpacity;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <opaque_fragment>',(settings.anime?`float facing=abs(dot(normalize(vAnimeNormal),normalize(vAnimeView)));float shade=.35+.65*floor(min(facing,.9999)*${(settings.animeSteps??3).toFixed(1)})/${((settings.animeSteps??3)-1).toFixed(1)};diffuseColor.rgb=mix(diffuseColor.rgb*shade*${settings.glow?'3.0':'1.0'},vec3(.008,.01,.018),1.0-step(${((settings.animeOutline??8)/100).toFixed(3)},facing));`:'')+'diffuseColor.a*=vInstanceOpacity;\n#include <opaque_fragment>');};bucket=new T.InstancedMesh(geometry,material,this.max);bucket.count=0;bucket.frustumCulled=false;this.scene.add(bucket);this.meshBuckets.set(key,bucket);}
  const index=bucket.count;if(index>=this.max)continue;const t=Math.min(particle.age/particle.life,1),radius=particle.size*(settings.size/(particle.birthSize||settings.size))*EmberLifetime.size(settings,t);position.set(particle.x,particle.y,particle.z);scale.setScalar(radius);quaternion.setFromAxisAngle(axis,particle.rotation||0);matrix.compose(position,quaternion,scale);bucket.setMatrixAt(index,matrix);color.set(EmberAnimation.particleColor(settings,t));bucket.setColorAt(index,color);bucket.geometry.attributes.instanceOpacity.array[index]=EmberLifetime.opacity(settings,t)*(settings.opacity??1);bucket.count++;
 }
 for(const bucket of this.meshBuckets.values()){bucket.visible=bucket.count>0;bucket.instanceMatrix.needsUpdate=true;if(bucket.instanceColor)bucket.instanceColor.needsUpdate=true;bucket.geometry.attributes.instanceOpacity.needsUpdate=true;}
};
